begin;

-- Russian Orthodox Church calendar 2026.
-- Source: Azbyka Orthodox Church Calendar 2026 daily pages.

delete from public.calendar_day_translations t
using public.calendar_days d
where t.calendar_day_id = d.id
  and d.country_code = 'RU'
  and d.calendar_code = 'ru-russian-orthodox-church'
  and d.calendar_date between date '2026-01-01' and date '2026-12-31';

delete from public.calendar_days
where country_code = 'RU'
  and calendar_code = 'ru-russian-orthodox-church'
  and calendar_date between date '2026-01-01' and date '2026-12-31';

insert into public.calendar_days (
  country_code, language_code, calendar_code, calendar_date,
  feast_rank, saints, title, details, fasting_note,
  editorial_source, is_published
) values
('RU','ru','ru-russian-orthodox-church','2026-01-01','cruce neagră',array[]::text[],'Мч. Вонифа́тия Тарсийского (290); Прп. Илии́ Муромца, Печерского, в Ближних пещерах (ок. 1188); мчч. Илии́, Прова и А́риса, еги́птян (308); мчч. Полие́вкта и Тимофе́я, диакона (IV); свт. Вонифа́тия Милостивого, епископа Ференти́йского (VI); свт. Григо́рия, епископа Омиритского (ок. 552)','Православный церковный календарь на 1 января 2026 года (четверг) - Седмица 30-я по Пятидесятнице. Мч. Вонифа́тия Тарсийского (290). Список всех церковных праздников и событий отмечаемых в эту дату.','Рождественский пост','Azbyka Orthodox Church Calendar 2026, https://azbyka.ru/days/',true),
('RU','ru','ru-russian-orthodox-church','2026-01-02','cruce neagră',array[]::text[],'Предпразднство Рождества Христова; Сщмч. Игна́тия Богоносца, епископа Антиохийского (107); свт. Анто́ния (Смирницкого), архиепископа Воронежского (1846); св. прав. Иоа́нна Кронштадтского (1908); Прп. Игна́тия, архимандрита Печерского, в Дальних пещерах (1435); свт. Филого́ния, епископа Антиохийского (ок. 323); свт. Дании́ла II, архиепископа Сербского (1337–1338); Сщмч. Николая Чернышева , пресвитера и мц. Варва́ры Чернышевой (1919); Иконы Божией Матери: Новодворская; Спасительница утопающих (Леньковская, Новгород-Северская)','Православный церковный календарь на 2 января 2026 года (пятница) - Седмица 30-я по Пятидесятнице. Предпразднство Рождества Христова. Список всех церковных праздников и событий отмечаемых в эту дату.','Рождественский пост','Azbyka Orthodox Church Calendar 2026, https://azbyka.ru/days/',true),
('RU','ru','ru-russian-orthodox-church','2026-01-03','cruce neagră',array[]::text[],'Предпразднство Рождества Христова; Мц. Иулиани́и и с нею 500 мужей и 130-ти жен, в Никомиди́и пострадавших (304); свт. Петра Московского, митрополита Киевского, всея Руси чудотворца (1326); Мц. благоверной княгини Иулиани́и Вяземской, Новоторжской (1406); блж. Проко́пия, Христа ради юродивого, Вятского (1627); свт. Филаре́та (Амфитеатрова), в схиме Феодо́сия, митрополита Киевского (1857); мч. Фемистокле́я Мирликийского (251); Сщмч. Михаила Киселева , пресвитера (1918); сщмч. Се́ргия Цветкова , диакона (1937); сщмч. Никиты (Прибыткова) , епископа Белевского (1938); сщмч. Лео́нтия Строцюка , диакона (1940)','Православный церковный календарь на 3 января 2026 года (суббота) - Седмица 30-я по Пятидесятнице. Предпразднство Рождества Христова. Список всех церковных праздников и событий отмечаемых в эту дату.','Рождественский пост','Azbyka Orthodox Church Calendar 2026, https://azbyka.ru/days/',true),
