('RU','ru','ru-russian-orthodox-church','2026-12-28','cruce neagră',array[]::text[],'Сщмч. Елевфе́рия, епископа, матери его мц. Анфи́и и мч. Кори́ва епарха (II); прп. Павла Латрийского (955); свт. Стефа́на исп., архиепископа Сурожского (VIII); Собор Крымских святых; сщмч. Иларио́на (Троицкого), архиепископа Верейского (1929); Прп. Три́фона Пе́ченгского, Кольского (1583); мч. Елевфе́рия Византийского (305–311); прп. Парда отшельника (VI); Сщмчч. Алекса́ндра Рождественского , Васи́лия Виноградова , Виктори́на Добронравова , пресвитеров (1937)','Православный церковный календарь на 28 декабря 2026 года (понедельник) - Седмица 31-я по Пятидесятнице. Сщмч. Елевфе́рия, епископа, матери его мц. Анфи́и и мч. Кори́ва епарха (II). Список всех церковных праздников и событий отмечаемых в эту дату.','Рождественский пост','Azbyka Orthodox Church Calendar 2026, https://azbyka.ru/days/',true),
('RU','ru','ru-russian-orthodox-church','2026-12-29','cruce neagră',array[]::text[],'Прор. Агге́я (500 г. до Р. Х.); Прп. Софи́и Суздальской (1542); мч. Мари́на Римского (III); блж. царицы Феофа́нии Византийской (893–894); Собор Кольских святых; Сщмч. Влади́мира Алексеева , пресвитера (1918); сщмчч. Арка́дия (Остальского) , епископа Бежецкого , Илии́ Чередеева , Павла Фаворитова , Влади́мира Дамаскина , Алекса́ндра Колоколова , Петра Зиновьева , пресвитеров, прмчч. Макария (Смирнова) , Феодо́сия (Болдырева) , иеромонахов (1937)','Православный церковный календарь на 29 декабря 2026 года (вторник) - Седмица 31-я по Пятидесятнице. Прор. Агге́я (500 г. до Р. Х.). Список всех церковных праздников и событий отмечаемых в эту дату.','Рождественский пост','Azbyka Orthodox Church Calendar 2026, https://azbyka.ru/days/',true),
('RU','ru','ru-russian-orthodox-church','2026-12-30','cruce neagră',array[]::text[],'Прор. Дании́ла и трех отроков: Ана́нии, Аза́рии и Мисаи́ла (VI–V вв. до Р. Х.); Прп. Дании́ла исп. (в схиме Стефа́на) Нивертского (X); Сщмчч. Алекса́ндра Савелова , Николая Бельтюкова и Се́ргия Флоринского , пресвитеров (1918); сщмчч. Петра Покровского и Иоа́нна Земляного , пресвитеров (1937)','Православный церковный календарь на 30 декабря 2026 года (среда) - Седмица 31-я по Пятидесятнице. Прор. Дании́ла и трех отроков: Ана́нии, Аза́рии и Мисаи́ла (VI–V вв. до Р. Х.). Список всех церковных праздников и событий отмечаемых в эту дату.','Рождественский пост','Azbyka Orthodox Church Calendar 2026, https://azbyka.ru/days/',true),
('RU','ru','ru-russian-orthodox-church','2026-12-31','cruce neagră',array[]::text[],'Мчч. Севастиа́на Медиоланского и дружины его: Никостра́та казнохранителя, жены его Зо́и, Касто́рия, Транквилли́на, пресвитера, и сынов его Маркелли́на и Марка, диаконов, Кла́вдия, начальника над тюрьмами, сына его Симфориа́на, брата Виктори́на, Тиву́ртия и Касту́ла (ок. 287); Прп. Севастиа́на Сохо́тского, Пошехо́нского (ок. 1500); прославление прав. Симео́на Верхотурского (Меркушинского) (1694); свт. Моде́ста, патриарха Иерусалимского (633–634); прп. Флора, епископа Ами́йского (VII); прп. Михаила Сингелла, исп. (ок. 845); прп. Даниила Пустынника, иеросхимонаха (Румын.); Мч. Ви́ктора Матвеева (1937); сщмчч. Фадде́я (Успенского) , архиепископа Тверского и Кашинского , Николая (Клементьева) , архиепископа Великоу́стюжского , Илии́ Бенеманского , Иоа́нна Миронского , Влади́мира Преображенского и Николая Кобранова , пресвитеров (1937); сщмч. Се́ргия Астахова , диакона и мц. Веры Трукс (1942)','Православный церковный календарь на 31 декабря 2026 года (четверг) - Седмица 31-я по Пятидесятнице. Мчч. Севастиа́на Медиоланского и дружины его: Никостра́та казнохранителя, жены его Зо́и, Касто́рия, Транквилли́на, пресвитера, и сынов его Маркелли́на и Марка, диаконов, Кла́вдия, начальника над тюрьмами, сына его Симфориа́на, брата Виктори́на, Тиву́ртия и Касту́ла (ок. 287). Список всех церковных праздников и событий отмечаемых в эту дату.','Рождественский пост','Azbyka Orthodox Church Calendar 2026, https://azbyka.ru/days/',true);

do $$
declare
  row_count integer;
  unique_count integer;
  first_date date;
  last_date date;
begin
  select count(*), count(distinct calendar_date), min(calendar_date), max(calendar_date)
    into row_count, unique_count, first_date, last_date
  from public.calendar_days
  where country_code = 'RU'
    and calendar_code = 'ru-russian-orthodox-church'
    and language_code = 'ru'
    and calendar_date between date '2026-01-01' and date '2026-12-31';

  if row_count <> 365 or unique_count <> 365 or first_date <> date '2026-01-01' or last_date <> date '2026-12-31' then
    raise exception 'Invalid RU calendar coverage: rows %, unique %, first %, last %', row_count, unique_count, first_date, last_date;
  end if;
end
$$;

commit;
